INSERT INTO news (title, summary, body, published_at, author_id) VALUES
  ('Запущена пробная версия модуля визуализации данных', 'Кафедра информационных систем начала опытную эксплуатацию модуля Витте-Дашборд.', 'Модуль подключается к единому центру статистических данных и строит интерактивные дашборды без ручной выгрузки в Excel. Опытная эксплуатация продлится пять рабочих дней.', NOW() - INTERVAL '0 days', (SELECT id FROM users WHERE login='admin')),
  ('Дашборд «Ключевые показатели» доступен руководству', 'Ректорат получил сводную панель из пяти ключевых показателей.', 'На панели отображаются численность студентов, динамика среднего балла, доля студентов без задолженностей, доля преподавателей со степенью и приём на первый курс.', NOW() - INTERVAL '3 days', (SELECT id FROM users WHERE login='admin')),
  ('Экспорт отчётов в Word и Excel', 'Сотрудники УМУ могут выгружать отчёты в форматах DOCX и XLSX.', 'В разделе «Отчёты» выбирается тип отчёта, период и факультет. История выгрузок сохраняется в личном кабинете пользователя.', NOW() - INTERVAL '6 days', (SELECT id FROM users WHERE login='admin')),
  ('Автоматическая синхронизация с 1С:Предприятие', 'Данные обновляются по кнопке «Обновить» и по расписанию — раз в час.', 'Администратор настраивает адрес HTTP-сервиса 1С в панели администратора и контролирует журнал синхронизации.', NOW() - INTERVAL '9 days', (SELECT id FROM users WHERE login='admin')),
  ('Разграничение прав доступа по ролям', 'В системе работают четыре роли: администратор, руководство, УМУ и деканат.', 'Деканат видит данные только своего факультета, руководство — все дашборды, а администратор управляет пользователями и справочниками.', NOW() - INTERVAL '12 days', (SELECT id FROM users WHERE login='admin')),
  ('Инструктаж для пользователей модуля', 'Для сотрудников УМУ пройдёт двухчасовой инструктаж.', 'Участникам будет выдано краткое руководство пользователя. Запись на инструктаж — через форму обратной связи.', NOW() - INTERVAL '15 days', (SELECT id FROM users WHERE login='admin'));
